test('should play voice preview', async ({ page }) => {
  // AI navigated, clicked, verified via MCP first
  await openTtsPanel(page);

  const voiceDropdown = page.getByTestId('voice-dropdown');
  await expect(voiceDropdown).toBeVisible();

  const playButton = voiceDropdown
    .getByTestId('voice-preview')
    .locator('.voice-preview__play-button');

  await playButton.click();
  await expect(playButton).toHaveClass(/--playing/);
});
